CREATE COLUMN TABLE "TEST_AP"."ZRD1" ("AbsEntry" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(8) NOT NULL , "Number" INTEGER CS_INT, "TotalSum" DECIMAL(21,6) CS_FIXED, "Descriptn" NVARCHAR(254), PRIMARY KEY ("AbsEntry", "LineNum")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "ZRD1_CODE" ON "TEST_AP"."ZRD1" ( "Code" ASC, "AbsEntry" ASC )